CREATE DATABASE IF NOT EXISTS temp_card CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE temp_card;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('admin','user','operator') NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE contractors (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL UNIQUE);
CREATE TABLE cards (id INT AUTO_INCREMENT PRIMARY KEY, barcode VARCHAR(32) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, national_code VARCHAR(10) NOT NULL, photo VARCHAR(255) NOT NULL, contractor_id INT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, access_area VARCHAR(255) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, disabled_reason VARCHAR(255) DEFAULT NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (contractor_id) REFERENCES contractors(id), FOREIGN KEY (created_by) REFERENCES users(id), INDEX (national_code), INDEX (created_at));
CREATE TABLE access_logs (id INT AUTO_INCREMENT PRIMARY KEY, card_id INT NOT NULL, operator_id INT NOT NULL, action ENUM('entry','exit') NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (card_id) REFERENCES cards(id), FOREIGN KEY (operator_id) REFERENCES users(id));
